"use strict";
(() => {
  const {esc,helpers:{add,code,flow,sequence,source}}=window.SNEAKER;
  const verified=window.SNEAKER_ORM_AUTH;
  Object.assign(source,{
    orm:['Описание ORM-моделей — SQLAlchemy 2.0','https://docs.sqlalchemy.org/en/20/orm/declarative_tables.html'],
    relation:['Связи объектов — SQLAlchemy 2.0','https://docs.sqlalchemy.org/en/20/orm/basic_relationships.html'],
    session:['Session и транзакция — SQLAlchemy 2.0','https://docs.sqlalchemy.org/en/20/orm/session_basics.html'],
    engine:['Engine и подключение — SQLAlchemy 2.0','https://docs.sqlalchemy.org/en/20/core/engines.html'],
    query:['SELECT в ORM — SQLAlchemy 2.0','https://docs.sqlalchemy.org/en/20/orm/queryguide/select.html'],
    migrations:['Устройство миграций — Alembic','https://alembic.sqlalchemy.org/en/latest/tutorial.html'],
    autogenerate:['Что умеет autogenerate — Alembic','https://alembic.sqlalchemy.org/en/latest/autogenerate.html'],
    bcrypt:['Проверка паролей — Passlib','https://passlib.readthedocs.io/en/stable/lib/passlib.hash.bcrypt.html'],
    jwt:['Структура и поля JWT — RFC 7519','https://www.rfc-editor.org/rfc/rfc7519.html'],
    jose:['Проверка JWT — python-jose','https://github.com/mpdavis/python-jose/blob/master/jose/jwt.py'],
    bearer:['Передача Bearer-токена — RFC 6750','https://www.rfc-editor.org/rfc/rfc6750.html'],
    auth:['Зависимости и доступ — FastAPI','https://fastapi.tiangolo.com/tutorial/security/oauth2-jwt/'],
    ormexamples:['Запустить примеры глав 7–8','sneaker-orm-auth-examples/README.md'],
    ormverified:['Проверки ORM, миграций и доступа','sneaker-orm-auth-examples/verification.json']
  });
  const c=(label,text)=>`<div class="oa-code">${code(label,esc(text))}</div>`;
  const panel=(title,text,color='')=>`<div class="db-panel ${color}"><h3>${title}</h3><p>${text}</p></div>`;
  const split=(a,b)=>`<div class="split db-layout">${a}${b}</div>`;
  const stack=(...a)=>`<div class="db-stack">${a.join('')}</div>`;
  const ribbon=text=>`<div class="db-ribbon">${text}</div>`;
  const result=(title,text)=>`<div class="oa-result"><div class="label">✓ ${title}</div><pre>${esc(text)}</pre></div>`;
  const table=(headers,rows)=>`<div class="oa-table"><table><thead><tr>${headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const control=(label,id,options)=>`<div class="db-controls"><label for="${id}">${label}</label><select id="${id}">${options.map(([key,title])=>`<option value="${key}">${title}</option>`).join('')}</select><span class="db-verified">✓ Проверенные результаты</span></div>`;

  add(73,'Как Python разговаривает с базой','SQLAlchemy связывает объекты Python и SQL-запросы.',`
    ${flow([['Python','Объекты и правила','yellow'],['SQLAlchemy','Выражения → SQL','purple'],['psycopg','Драйвер соединения','mint'],['PostgreSQL','Выполняет SQL','yellow']])}
    ${ribbon('<code>postgresql+psycopg://…</code><span>База PostgreSQL + явно выбранный драйвер psycopg</span>')}`,
    'ORM упрощает работу с таблицами через объекты. SQL и ограничения базы продолжают действовать.',
    ['В прошлой главе мы писали SELECT и INSERT вручную. Теперь хотим выразить те же действия в Python: найти Product, обратиться к его brand и сохранить новый объект. ORM означает object-relational mapping — сопоставление объектов программы со строками реляционной базы. SQLAlchemy также умеет работать с SQL без ORM.',
     'SQLAlchemy строит SQL и передаёт выполнение драйверу psycopg. Драйвер устанавливает соединение, отправляет команды и получает значения. PostgreSQL выполняет запросы и применяет ограничения. Если сохранить отрицательную цену через ORM, CHECK не перестаёт действовать: ошибка придёт обратно в Python.',
     'В задании используется синхронный SQLAlchemy 2.0. В примерах обычные def и Session, а не AsyncSession. Суффикс +psycopg в строке подключения выбирает установленный драйвер. Сама установка SQLAlchemy не создаёт базу, таблицы или миграции. Учебные примеры этой главы работают в отдельной схеме PostgreSQL, сохраняя данные предыдущих уроков.'],
    'Если перейти на ORM, можно забыть о JOIN, ключах и транзакциях?', 'Нет. ORM использует те же механизмы базы, поэтому нужно понимать, какие запросы и изменения он выполняет.', ['engine','orm','ormexamples']);
  add(74,'ORM-модель описывает таблицу','Класс Product связывает атрибуты Python со столбцами products.',split(
    c('models.py · сокращённый фрагмент','class Product(Base):\n    __tablename__ = "products"\n    id: Mapped[int] = mapped_column(\n        Identity(), primary_key=True)\n    name: Mapped[str] = mapped_column(Text)\n    price: Mapped[Decimal] = mapped_column(\n        Numeric(10, 2))'),
    table(['Python','PostgreSQL'],[['Product','products'],['id: int','integer · PRIMARY KEY'],['name: str','text · NOT NULL'],['price: Decimal','numeric(10,2)']])) ,
    'Класс задаёт соответствие. Таблицу в нашем приложении создаёт миграция.',
    ['Base наследуется от DeclarativeBase и собирает описания таблиц в metadata. __tablename__ задаёт имя таблицы. Mapped[int] означает атрибут ORM с Python-типом int, а mapped_column уточняет столбец: тип базы, ключ, ограничение или значение по умолчанию. В id генератор Identity выдаёт число при вставке.',
     'В типизированном отображении SQLAlchemy Mapped[str] без None обычно задаёт обязательный столбец, если nullable не переопределён явно. Mapped[str | None] допускает NULL. Numeric(10,2) связан с точным Decimal. Правило price > 0 в полном классе объявлено отдельным CheckConstraint: один тип не проверяет положительность.',
     'На экране только несколько полей; полный models.py содержит все семь таблиц, внешние ключи и ограничения. Определение класса не выполняет CREATE TABLE. Metadata — описание желаемой структуры в Python; реальную структуру изменяет применённая миграция. Создание Product(...) также ещё не означает запись строки.'],
    'Что случится в базе сразу после определения class Product?', 'Ничего. Python зарегистрирует описание модели, но таблица сама не появится.', ['orm','ormexamples']);
  add(75,'ForeignKey и relationship: две роли','Ссылка защищает данные. Связь объектов помогает читать Python-код.',split(
    c('Product · фрагмент модели','brand_id: Mapped[int] = mapped_column(\n    ForeignKey("brands.id"))\n\nbrand: Mapped[Brand] = relationship(\n    back_populates="products")'),
    stack(panel('ForeignKey → правило БД','<code>brand_id=1</code> должен указывать на существующий <code>brands.id</code>.','yellow'),panel('relationship → объект Python','<code>product.brand.name</code><br>→ <b>North</b>','mint'))),
    'relationship не добавляет отдельный столбец brand. Связь в базе хранится через brand_id.',
    ['ForeignKey("brands.id") описывает внешний ключ. После применения соответствующей миграции PostgreSQL запрещает ссылку на несуществующий бренд. relationship задаёт ORM-связь: атрибут product.brand возвращает объект Brand, а не просто число. На стороне Brand есть products и обратный back_populates="brand".',
     'Число brand_id=1 физически хранится в строке products. Атрибут brand не становится дополнительной колонкой с вложенным объектом. SQLAlchemy использует условия связи, чтобы получить нужную строку brands и представить её как объект Python. В нашем реальном запросе product.brand.name вернул North.',
     'Чтение relationship может вызвать дополнительный SELECT, если связанные данные ещё не загружены. Если так читать бренд в цикле по сотне товаров, легко получить много запросов. Позже можно загрузить связи заранее, например selectinload. После закрытия Session незагруженную связь обычно уже нельзя просто дочитать. Поэтому структура ORM важна и для производительности, и для времени жизни объектов.'],
    'Заменит ли relationship ограничение внешнего ключа в PostgreSQL?', 'Нет. relationship организует работу с объектами, а внешний ключ обеспечивает ссылочную целостность в базе.', ['relation','ormverified']);
  add(76,'Engine и Session работают вместе','Engine управляет подключениями. Session сопровождает одну работу с данными.',split(
    c('database.py · идея настройки','engine = create_engine(DATABASE_URL)\nSessionLocal = sessionmaker(engine)\n\nwith SessionLocal() as session:\n    product = session.get(Product, 10)'),
    stack(panel('Engine · на приложение','Знает драйвер и адрес. Обычно управляет пулом соединений.','purple'),panel('Session · на операцию / запрос','Отслеживает ORM-объекты и текущую транзакцию.','mint'))),
    'Engine можно переиспользовать. Одну Session нельзя одновременно разделять между запросами.',
    ['Engine обычно создают один раз на процесс приложения и связывают с DATABASE_URL. Его создание ещё не доказывает, что база доступна: реальное соединение обычно запрашивается при первом обращении к данным. Пул позволяет возвращать соединения и брать их повторно вместо нового подключения на каждый SQL-запрос.',
     'sessionmaker создаёт фабрику Session с общей настройкой. Для отдельного запроса получаем отдельную сессию. Она следит за загруженными и изменёнными объектами, выполняет запросы и управляет границей транзакции. Session — не подключение навсегда: она получает соединение по необходимости и освобождает ресурс при завершении работы.',
     'Блок with SessionLocal() закрывает сессию при выходе. Он сам по себе не фиксирует изменения: commit должен быть явным либо организованным отдельным транзакционным контекстом. Одна Session не предназначена для одновременного использования независимыми запросами. В учебном FastAPI зависимость get_db выдаёт новую сессию и закрывает её после обработки.'],
    'Можно ли сделать одну глобальную Session для всех покупателей?', 'Нет. У запросов должны быть отдельные сессии. Общим обычно остаётся Engine и фабрика SessionLocal.', ['engine','session','ormexamples']);
  add(77,'SELECT возвращает объект или None','Ищем по первичному ключу: совпадений будет не больше одного.',`
    ${control('Ищем товар:','orm-product',[['10','ID 10 · существует'],['999','ID 999 · отсутствует']])}
    <div id="orm-product-result" aria-live="polite"></div>`,
    'Конструктор select описывает запрос. session.scalar выполняет его и берёт первое скалярное значение.',
    ['Выражение select(Product).where(Product.id == product_id) строит SQL-запрос к полям модели с условием по ID. Само построение выражения не обращается к базе. Выполнение начинается при session.scalar(stmt). Поскольку выбираем ORM-сущность, скалярным значением результата будет объект Product.',
     'Для id=10 находим North Runner с Decimal-ценой 7990.00. Для id=999 получаем None. Попытка сразу читать product.name у None приведёт к ошибке Python, поэтому обработчик должен отдельно решить случай отсутствия записи, например вернуть HTTP 404.',
     'Уникальность результата здесь следует из PRIMARY KEY. session.scalar в общем случае не доказывает, что строка была ровно одна; если требуется контроль не более одной строки, используют scalar_one_or_none у результата execute. Для списка объектов подходит session.scalars(stmt).all(). Значения из запроса передаются как параметры, а не вставляются конкатенацией в SQL.'],
    'Что вернёт запрос по несуществующему ID и где превратить это в 404?', 'Запрос вернёт None. Контролируемый HTTP-ответ формирует обработчик API или согласованный слой обработки ошибок.', ['query','ormverified']);
  add(78,'Таблица, схема API и JSON','Три представления одного товара решают разные задачи.',`
    <div class="oa-three">${panel('ORM · Product','Столбцы, ключи, связи.<br><code>price: Decimal</code>','purple')}${panel('Pydantic · ProductRead','Поля публичного ответа.<br><code>from_attributes=True</code>','yellow')}${panel('JSON · ответ','Текст для клиента.<br><code>"price": "7990.00"</code>','mint')}</div>
    ${c('Проверенное преобразование','dto = ProductRead.model_validate(product)\npayload = dto.model_dump(mode="json")')}`,
    'ORM-модель хранит данные, схема API выбирает контракт. Их поля не обязаны совпадать.',
    ['Product — объект, отображённый на таблицу. В нём есть brand_id, description, image_url, created_at и ORM-связь brand. ProductRead из примера содержит только id, name и price: столько мы решили отдавать клиенту в этом коротком ответе. Отсутствие поля в ответе не удаляет столбец из базы.',
     'ConfigDict(from_attributes=True) позволяет Pydantic читать значения атрибутов ORM-объекта. model_validate строит и проверяет модель ответа. model_dump(mode="json") превращает значения в JSON-совместимые; в выбранной версии Pydantic Decimal сериализуется строкой "7990.00", что подтверждено проверкой. Сам словарь Python ещё не является сетевой передачей; FastAPI затем сформирует HTTP-ответ.',
     'Особенно важно разделение для User: внутренняя модель содержит hashed_password, а UserRead в примере — только id и email. Нельзя бездумно отдавать __dict__ ORM-объекта. Если схема ответа читает незагруженные связи, сериализация может вызвать запросы или столкнуться с закрытой сессией; нужные данные загружают заранее.'],
    'Нужно ли показывать клиенту каждый столбец users?', 'Нет. Публичная схема должна содержать только предусмотренные контрактом поля; hashed_password в неё не входит.', ['response','ormexamples','ormverified']);
  add(79,'add, flush и commit — разные шаги','Посмотрим, когда появился ID и когда строку увидит другое соединение.',`
    ${control('Состояние после:','orm-write',[['0','1 · Создали объект'],['1','2 · session.add'],['2','3 · session.flush'],['3','4 · session.commit']])}
    <div id="orm-write-result" aria-live="polite"></div>
    <div class="oa-print-only">${table(['Шаг','ID','Виден другому соединению'],verified.orm.write_states.map(s=>[s.step,s.id??'None',s.visible_elsewhere?'Да':'Нет']))}</div>`,
    'flush отправляет изменения в текущую транзакцию. commit фиксирует её результат.',
    ['Создание Product(...) даёт обычный объект ORM в памяти. session.add(product) включает его в работу сессии как новую запись, но в показанном примере SQL ещё не отправлен. session.flush() выполняет INSERT. PostgreSQL выдаёт ID, и ORM записывает его обратно в объект. Мы можем использовать этот ID в связанных строках той же транзакции.',
     'После flush независимое соединение в нашем стандартном режиме READ COMMITTED ещё не видит новую строку. После успешного commit новая транзакция другого соединения её находит. Это проверено двумя настоящими сессиями PostgreSQL. Само наличие ID не доказывает фиксацию: откат может удалить вставку, оставив пропуск в последовательности.',
     'commit при необходимости сначала выполняет flush, поэтому отдельный flush нужен не всегда. Перед некоторыми ORM-запросами flush может запускаться автоматически — это autoflush. По умолчанию commit также помечает загруженные атрибуты как требующие обновления при следующем чтении. На слайде результаты последовательного опыта; переключатель показывает его сохранённые состояния, а не создаёт строки заново.'],
    'После flush появился ID. Можно ли уже сообщить клиенту, что покупка точно сохранена?', 'Нет. Транзакция может откатиться или commit может завершиться ошибкой. Факт присвоения ID не равен успешной фиксации.', ['session','ormverified']);
  add(80,'У сессии должно быть завершение','Успех фиксируем. Ошибку откатываем. Соединение освобождаем.',split(
    c('Отдельная операция · новая Session','with Session(engine) as session:\n    with session.begin():\n        session.add(Brand(name="Demo"))\n        session.flush()\n        # Исключение → rollback\n    # Успех → commit\n# Выход → close'),
    stack(panel('Ошибка после flush','Строка из опыта отсутствует после отката.','yellow'),panel('После неудачного flush','Перед повторным использованием той же Session вызываем <code>rollback()</code>.','mint'))),
    'Граница транзакции должна иметь одного владельца. close не заменяет commit.',
    ['В этом фрагменте новая Session ещё не выполняла запросов. Внутренний with session.begin() задаёт явный транзакционный блок: успешный выход фиксирует изменения, исключение вызывает откат и проходит дальше. Внешний with закрывает сессию. Ошибка, специально вызванная после flush в проверке, не оставила строку в базе.',
     'Если мы перехватили IntegrityError от flush и хотим продолжить работать именно с той же Session, нужен явный rollback. Иначе сессия остаётся в состоянии неудачной транзакции. Исключение нельзя просто проглотить и вернуть клиенту успех: это скрывает фактический отказ записи.',
     'В SQLAlchemy обычный SELECT тоже может автоматически начать транзакцию — autobegin. Поэтому нельзя после чтения текущего пользователя бездумно открыть session.begin() на той же сессии: транзакция уже может идти. В приложенном API запись регистрации использует явный commit и rollback; фрагмент здесь показывает отдельную операцию на свежей Session. Границу сложного оформления согласуем в главе 9.'],
    'Можно ли открыть session.begin() после любого SELECT без проверки границы?', 'Нет. SELECT мог уже начать транзакцию. Нужно заранее выбрать одного владельца её начала и завершения.', ['session','ormverified']);
  add(81,'Изменить класс — мало','Код уже ожидает image_url, а в таблице такого столбца ещё нет.',split(
    stack(c('Новая версия модели','image_url: Mapped[str | None] = (\n    mapped_column(Text)\n)'),panel('Python ожидает','id · name · price · <b>image_url</b>','purple')),
    stack(panel('База пока на версии 0001','id · name · price<br><b>image_url отсутствует</b>','yellow'),result('Проверенный отказ','SQLSTATE 42703\nundefined_column'))),
    'Код и структура базы версионируются согласованно. Новый атрибут не выполняет ALTER TABLE.',
    ['Для опыта взята отдельная учебная схема. Первая миграция создаёт семь таблиц, но ещё без необязательного image_url. Текущая модель Product уже содержит это поле. При обычном select(Product) ORM запрашивает все отображённые столбцы, и PostgreSQL возвращает undefined_column с кодом 42703.',
     'Этот пример иллюстрирует эволюцию схемы, а не изменяет набор таблиц из предыдущей главы. Добавление строки в models.py описывает новое желаемое состояние. Существующая база не перечитывает Python и не перестраивает таблицы сама. Ей нужна команда изменения схемы, оформленная как миграция.',
     'metadata.create_all может создать отсутствующие таблицы, но не является универсальным механизмом обновления уже существующих таблиц. Запускать его вместо миграций на каждом старте приложения не решает историю изменений. В следующем шаге добавим столбец миграцией и повторим тот же запрос.'],
    'Почему запрос упал, хотя в Python image_url объявлен?', 'Потому что SQL обращается к реальной таблице, где миграция с этим столбцом ещё не применена.', ['migrations','ormverified']);
  add(82,'Миграция хранит шаг изменения','Alembic применяет явные операции к структуре базы.',split(
    c('0002_image_url.py · исполняемый фрагмент','def upgrade():\n    op.add_column("products",\n        sa.Column("image_url",\n                  sa.Text(), nullable=True))\n\ndef downgrade():\n    op.drop_column("products", "image_url")'),
    stack(panel('Было · 0001','У products нет image_url.','yellow'),panel('Стало · 0002','Столбец появился.<br>У существующих строк — NULL.','mint'))),
    'upgrade двигает схему вперёд. downgrade может удалить данные, поэтому его последствия читаем отдельно.',
    ['Миграция — Python-файл с идентификатором версии, ссылкой на предыдущую версию и операциями изменения. upgrade добавляет nullable-столбец image_url типа text. Это действие меняет PostgreSQL, а не только описание модели. Для уже существующих строк без значения новый необязательный столбец будет NULL.',
     'downgrade в этом конкретном файле удаляет столбец. Если в него уже записали ссылки на изображения, они будут потеряны: обратная структурная операция не восстанавливает исчезнувшие значения из воздуха. Перед откатом нужно понимать данные и способ восстановления. Учебная проверка выполняет upgrade, downgrade и повторный upgrade на одноразовой схеме.',
     'Здесь простое изменение без обязательного заполнения. Для нового NOT NULL-поля в непустой таблице часто нужен поэтапный переход: добавить поле, заполнить существующие строки, затем установить ограничение. Для переименования важно сохранить данные операцией rename, а не случайной парой drop/add. Миграцию рассматривают как код, который изменит реальную базу.'],
    'Вернёт ли downgrade удалённые значения image_url при последующем upgrade?', 'Нет. Повторное создание столбца не восстанавливает его прежние данные.', ['migrations','ormexamples']);
  add(83,'Версии складываются в цепочку','Файлы миграций описывают путь. База помнит применённую ревизию.',`
    ${flow([['Пустая схема','Нет таблиц','yellow'],['0001','Семь таблиц','purple'],['0002 · head','Добавлен image_url','mint']])}
    ${split(c('В папке учебных примеров','python -m alembic history\npython -m alembic current\npython -m alembic upgrade head'),panel('alembic_version','После upgrade: <b>0002</b><br>head — последняя ревизия нашей линейной цепочки.','mint'))}`,
    'Миграция в репозитории и применённая миграция в базе — два разных состояния.',
    ['revision идентифицирует файл миграции, down_revision указывает его предшественника. В примере 0001 имеет down_revision=None, а 0002 ссылается на 0001. Alembic строит граф зависимостей и применяет недостающие шаги, чтобы база дошла до целевой ревизии.',
     'history показывает известную историю из файлов, current — состояние подключённой базы. upgrade head применяет путь к конечной ревизии. В нашей простой цепочке head один; при параллельной разработке возможны ветви и несколько heads, которые нужно осознанно согласовать. alembic_version хранит отметку версии, а не копию всех SQL-команд.',
     'Команды выполняются из sneaker-orm-auth-examples с настроенным .env и отдельной схемой. Нельзя путать наличие файла 0002 в Git с применением его в конкретной базе. stamp только меняет отметку версии без выполнения миграций, поэтому не лечит отсутствие столбца. Совпадение структуры с metadata дополнительно проверено после upgrade.'],
    'В репозитории есть 0002, а current показывает 0001. Чего не хватает?', 'Применения миграции к этой базе: после проверки файла выполняем upgrade до нужной ревизии.', ['migrations','ormverified']);
  add(84,'autogenerate предлагает черновик','Alembic сравнивает metadata с базой, а человек проверяет смысл изменений.',split(
    stack(c('После изменения models.py','python -m alembic revision --autogenerate \\\n  -m "add image_url"'),panel('Перед upgrade читаем файл','Имена таблиц · типы · nullable<br>upgrade · downgrade · сохранность данных','mint')),
    panel('Опасная догадка при rename','<code>drop_column("name")</code><br>+ <code>add_column("title")</code><br><br>Так можно потерять старые названия.','yellow')),
    'Автогенерация видит различие структур. Намерение переименовать поле она надёжно не угадывает.',
    ['Для сравнения в migrations/env.py передаём target_metadata=Base.metadata и импортируем все нужные модели. Если модель не зарегистрирована, Alembic может неверно решить, что таблица не нужна. Также важно, к какой базе и схеме подключена команда: сравнение с чужим состоянием даст другой черновик.',
     'revision --autogenerate создаёт файл-кандидат; эта команда сама не применяет upgrade. Читаем каждую операцию: не удаляется ли нужная таблица, совпадают ли типы и обязательность, что станет с существующими строками. Возможности обнаружения зависят от версии и конфигурации; бизнес-преобразования данных всё равно требуют отдельного решения.',
     'Переименование колонки часто выглядит для сравнения как удаление старой и добавление новой. Если это именно rename, нужно заменить операции на корректное переименование и проверить данные. Приведённая команда иллюстрирует создание новой миграции: в готовом стенде 0002 уже есть, поэтому не надо создавать её второй раз без изменения модели. Проверенный initial-файл также получен автогенерацией и затем просмотрен.'],
    'Можно ли сразу выполнить upgrade после autogenerate, не открывая файл?', 'Нельзя считать результат автоматически правильным. Сначала проверить операции и их влияние на существующие данные.', ['autogenerate','ormexamples']);
  add(85,'Seed добавляет строки после миграции','Сначала появляются таблицы, затем учебные бренды, товары и пользователи.',split(
    c('seed.py · идея вставки бренда','stmt = insert(Brand).values(\n    id=1, name="North"\n).on_conflict_do_nothing()\n\nwith engine.begin() as connection:\n    connection.execute(stmt)'),
    stack(table(['Повтор seed','Бренды','Товары'],[['Первый запуск',2,3],['Второй запуск',2,3]]),panel('Повторяемость имеет правила','Существующие строки сохраняются.<br>Seed не сбрасывает корзины и цены.','mint'))),
    'Миграция управляет структурой. Seed даёт конкретные данные для разработки и проверки.',
    ['В примере insert импортируется из sqlalchemy.dialects.postgresql: on_conflict_do_nothing — PostgreSQL-вариант вставки. При конфликте уникальности эта строка пропускается. Полный seed обрабатывает семь таблиц в порядке зависимостей: сначала родители, затем строки с внешними ключами.',
     'Повторный запуск проверен: количество строк не выросло, уже существующий хэш пользователя не заменился. В этом учебном наборе заданы фиксированные ID и уникальные значения, поэтому поведение воспроизводимо. В реальном seed нужно дополнительно решить, что делать, если ID занят другой сущностью или данные уже отредактированы; слепое игнорирование любого конфликта не является универсальной политикой.',
     'Seed не равен сбросу базы. Он не очищает корзину, не меняет текущую цену и не перезаписывает изменённые строки. Учебные пользователи имеют явно обозначенные демонстрационные пароли, а администратор создаётся локально, не через публичную регистрацию. После явной вставки ID генераторы синхронизируются, чтобы последующие записи не столкнулись с ними.'],
    'Можно ли запустить seed до создания таблиц?', 'Нет. Сначала применяем миграции к нужной схеме, затем добавляем записи.', ['ormexamples','ormverified']);
  add(86,'Слои помогают проследить запрос','Каждый файл отвечает за понятную часть пути от HTTP до данных.',`
    <div class="oa-layers">${[
      ['routers / api.py','Принять запрос, зависимости, HTTP-ответ'],['schemas.py','Поля входа и публичного ответа'],['services.py','Правила сценария: что разрешено сделать'],['models.py','Таблицы и связи ORM'],['database.py + core','Сессии, подключения и настройки']
    ].map(([a,b],i)=>`<div data-step="${i}"><code>${a}</code><span>${b}</span></div>`).join('')}</div>
    <p class="db-caption">GET /products/10 → роутер → поиск товара → Product → ProductRead → JSON</p>`,
    'Разделение файлов помогает читать и проверять код. Граница транзакции всё равно должна быть явной.',
    ['В полном проекте роутер отвечает за HTTP-контракт и зависимости. Схемы Pydantic описывают вход и ответ. Сервис объединяет правила сценария, например оформление заказа. ORM-модели описывают таблицы, database управляет подключением и сессиями, core хранит настройки и общие механизмы.',
     'Пройдите мысленно один запрос: роутер получает ID, использует сессию для поиска, обрабатывает отсутствие товара, затем отдаёт данные через ProductRead. Разделение не требует создавать десятки пустых файлов. В коротком учебном стенде маршруты собраны в api.py; изображённая структура показывает, как расширять полноценный магазин.',
     'Не стоит прятать commit в каждом маленьком вспомогательном методе: тогда сложный сценарий потеряет единую транзакцию. Передавать одну Session через согласованный участок операции нормально, а делить её между независимыми одновременными запросами — нет. В следующей главе добавим зависимости, которые устанавливают пользователя и проверяют его доступ.'],
    'Почему commit внутри каждой маленькой функции усложняет оформление заказа?', 'Промежуточные изменения могут зафиксироваться раньше остальных. Откат уже не сможет вернуть весь сценарий к исходному состоянию.', ['routers','session','plan']);
  add(87,'Зачем магазину знать пользователя','Аня и Борис обращаются к одному API, но работают со своими данными.',split(
    panel('Аня · user_id=7','Корзина: позиции <b>55, 56</b><br>Заказ: <b>501</b>','purple'),
    stack(panel('Борис · user_id=8','Корзина: позиция <b>57</b><br>Заказ 501 ему не принадлежит.','yellow'),panel('Тело запроса не подтверждает личность','<code>{"user_id": 7}</code><br>может написать любой клиент.','mint'))),
    'Текущего пользователя сервер устанавливает по проверенным учётным данным, а не по заявленному user_id.',
    ['Каталог можно читать публично, если это разрешено контрактом. Корзина и история заказов персональные: перед выборкой нужно понять, кто именно прислал запрос. Знакомые ID 7 и 8 описывают разных покупателей даже тогда, когда они выбирают одинаковые кроссовки.',
     'Если доверять user_id из JSON или query-параметра, Борис просто подставит 7 и представится Аней. Поэтому для личных операций сервер получает пользователя из механизма входа и проверенного токена. Для чтения своего заказа user_id вообще не нужно принимать от клиента как источник прав.',
     'Это не делает каждый запрос автоматически разрешённым. После установления пользователя ещё проверяются владелец конкретной записи или роль. Токен Бориса может быть полностью корректным, но заказ 501 всё равно остаётся заказом Ани. Эту границу покажем реальным запросом от второго аккаунта.'],
    'Если клиент прислал user_id=7, доказано ли, что запрос отправила Аня?', 'Нет. Клиент может подставить любое число. Личность устанавливается отдельной проверкой.', ['auth','plan']);
  add(88,'Кто ты — и что тебе разрешено','Аутентификация и авторизация отвечают на разные вопросы.',`
    <div class="oa-two-gates">${panel('1 · Аутентификация','Токен проверен → пользователь <b>7</b>.<br>«Кто обращается?»','purple')}<span aria-hidden="true">→</span>${panel('2 · Авторизация','Пользователь 7 владеет заказом 501.<br>«Разрешено ли это действие?»','mint')}</div>
    ${table(['Ситуация','Ответ в нашем API'],[['Нет действительных данных входа','401 · требуется аутентификация'],['Вошёл, но нет роли администратора','403 · действие запрещено'],['Заказ чужой или отсутствует','404 · не раскрываем чужую запись']])}`,
    'Успешный вход подтверждает пользователя. Разрешение проверяется для каждой защищённой операции.',
    ['Аутентификация устанавливает пользователя: например, сервер проверил JWT и нашёл соответствующую запись users. Авторизация проверяет, имеет ли этот пользователь доступ к операции или ресурсу. Для админского действия важно is_admin, для личного заказа — совпадение владельца.',
     'В учебном API недействительный или отсутствующий токен даёт 401 с WWW-Authenticate: Bearer. Пользователь установлен, но не администратор — 403. Для чтения чужого заказа выбрано 404: клиент не получает подтверждения существования чужой записи. Это осознанная политика нашего примера, а не единственный возможный код для любой системы.',
     'Проверка прав должна выполняться на сервере. Скрытая кнопка в интерфейсе не мешает человеку отправить HTTP-запрос вручную. Также нельзя считать, что успешный доступ к одному маршруту автоматически разрешает другой: каждый защищённый сценарий подключает необходимые зависимости и условия выборки.'],
    'Валидный токен обычного пользователя даёт право создавать товары?', 'Нет. Он подтверждает пользователя; админские действия требуют отдельной проверки роли.', ['http','auth','ormverified']);
  add(89,'Регистрация создаёт пользователя','Пароль нужен для входа, но не должен попасть в публичный ответ.',`
    ${flow([['Ввод','email + password','yellow'],['Проверки','Формат + уникальность','purple'],['Хэш','bcrypt с солью','mint'],['users','is_admin = false','yellow']])}
    ${split(c('POST /auth/register · пример','{"email": "new@example.com",\n "password": "New-demo-N1!"}'),result('Фактический ответ · 201',JSON.stringify(verified.auth.register.body,null,2)))}`,
    'Публичная регистрация не принимает is_admin. Повтор email запрещён также ограничением базы.',
    ['Pydantic проверяет формат email и выбранные требования к паролю. В стенде политика email явно приводит значение к нижнему регистру; так поиск и сохранение используют одно правило. Это проектное решение для идентификаторов аккаунтов, которое нужно согласовать, а не универсальное свойство всех адресов электронной почты.',
     'Далее проверяем отсутствие email, вычисляем хэш и создаём User с is_admin=False. Предварительный SELECT удобен для понятной ошибки, но два одновременных запроса всё ещё могут пройти его вместе. Последнюю защиту обеспечивает UNIQUE(email); ожидаемый конфликт записи ловим, делаем rollback и возвращаем 409.',
     'Credentials настроена с extra="forbid": попытка прислать is_admin или другое лишнее поле даёт 422. Публичный UserRead содержит только id и email. Пароль и hashed_password не входят в ответ. На экране вымышленный демонстрационный пароль; реальные пароли не сохраняют в логах и не пересылают в промптах. Проверки выполнены через настоящий обработчик и PostgreSQL.'],
    'Зачем UNIQUE(email), если перед вставкой уже был SELECT?', 'Параллельные запросы могут одновременно не найти пользователя. Ограничение базы защищает от дубликата в момент записи.', ['pg','bcrypt','ormexamples','ormverified']);
  add(90,'Пароль проверяем по хэшу','bcrypt использует случайную соль: один пароль может дать разные хэши.',split(
    c('security.py · фрагмент использования','hashed = pwd_context.hash(password)\n\npwd_context.verify(password, hashed)\n# True\n\npwd_context.verify("wrong", hashed)\n# False'),
    stack(result('Проверено с Passlib + bcrypt','Хэши одного пароля различаются: True\nВерный пароль проходит: True\nНеверный пароль проходит: False'),panel('Обратной расшифровки нет','verify повторяет проверку с параметрами из сохранённого хэша.','mint'))),
    'Храним хэш, а не пароль. Соль не секретна; она сохраняется вместе с параметрами проверки.',
    ['Хэширование пароля — специально затратная односторонняя проверка. При регистрации bcrypt выбирает случайную соль и формирует сохранённую строку с параметрами алгоритма. При входе verify использует эту строку и предъявленный пароль. Две независимые операции hash для одного пароля дают разные строки, но обе позволяют проверить тот же пароль.',
     'Не нужно вычислять новый hash и сравнивать его строку с прежней: новая соль изменит результат. Нельзя и расшифровать хэш для отправки старого пароля пользователю. Хэши всё равно являются чувствительными данными: утечка позволяет подбирать пароли, поэтому их не публикуют в API и не копируют в логи.',
     'Сохраняем стек задания passlib[bcrypt]. Проверенная пара в стенде — passlib 1.7.4 и bcrypt 4.0.1; совместимость пакетов нельзя выводить только из названия библиотеки. Для bcrypt явно ограничиваем пароль 72 байтами UTF-8 и включаем truncate_error. Проверка по символам недостаточна: 40 кириллических букв могут занимать 80 байт. Не обрезаем пароль молча.'],
    'Почему нельзя при логине сделать hash(input) == stored_hash?', 'Новый hash получит новую соль и обычно другую строку. Проверять нужно verify(input, stored_hash).', ['bcrypt','ormverified']);
  add(91,'Логин выдаёт временный токен','Сначала проверяем пароль, затем создаём подтверждение для следующих запросов.',`
    ${sequence('Логин: клиент, API, база',['Клиент','API','PostgreSQL'],[
      [0,1,'POST /auth/login · email + password'],[1,2,'Найти users по email'],[2,1,'Пользователь + сохранённый хэш'],[1,0,'Пароль верен → 200 + access_token']
    ])}
    <p class="db-caption">Неверный пароль или неизвестный email → одинаковый ответ <b>401</b>.</p>`,
    'Токен выдаём только после проверки. Пароль не кладём в токен и не отправляем в следующих запросах.',
    ['В учебном стенде /auth/login принимает JSON с email и password. Это простой контракт урока; он не использует OAuth2-форму password grant. Сервер ищет пользователя по принятому правилу нормализации email и вызывает verify_password. При успехе выдаёт JSON с access_token и token_type="bearer".',
     'Для неверного пароля и отсутствующего пользователя возвращается одинаковое сообщение Invalid credentials и статус 401. Для отсутствующего пользователя в стенде также выполняется проверка демонстрационного хэша, чтобы не пропускать полностью затратную операцию. Это уменьшает явные различия пути, но не является доказательством идеального равенства времени ответа.',
     'После входа клиент хранит выданный токен и предъявляет его в следующих запросах. JWT — не доказательство знания пароля в каждом новом запросе: достаточно владеть токеном. Поэтому в реальном сетевом обмене нужен HTTPS, а ограничения частоты попыток входа и выбранная политика хранения токена относятся к полноценной реализации. Короткий пример здесь показывает сам механизм, без refresh-токенов и полного управления сессиями.'],
    'Должен ли клиент отправлять пароль вместе с каждым GET /auth/me?', 'Нет. После входа он предъявляет выданный Bearer-токен; сервер проверяет его и находит пользователя.', ['auth','bearer','ormexamples']);
  add(92,'JWT: данные и подпись','Подписанный JWT в нашем примере состоит из трёх частей.',`
    <div class="oa-jwt"><div><b>header</b><span>Алгоритм и тип</span></div><strong>.</strong><div><b>payload</b><span>Утверждения о доступе</span></div><strong>.</strong><div><b>signature</b><span>Проверка целостности</span></div></div>
    ${split(c('Payload · из проверенного примера',JSON.stringify(verified.auth.claims,null,2)),panel('Подпись не скрывает данные','Header и payload можно прочитать.<br><br><code>exp</code> — момент истечения в Unix-секундах. Пароля здесь нет.','yellow'))}`,
    'Проверяем подпись и обязательные поля. Простое декодирование payload не подтверждает подлинность.',
    ['На экране подписанный compact JWT, используемый в уроке. Header описывает алгоритм HS256 и тип JWT; payload содержит claims; signature проверяет, что подписанные данные не были изменены без ключа. Header и payload кодируются Base64URL, что позволяет прочитать их без секрета. Это не шифрование. JWT как стандарт допускает и другие формы, но здесь разбираем именно подписанный вариант.',
     'sub — строковый идентификатор пользователя "7". exp в настоящем токене — число секунд от Unix epoch, после которого токен недействителен. На экране декодированные данные реально проверенного учебного токена. Значение exp — абсолютный момент времени, а не число минут до истечения. iss указывает издателя, aud — получателя. Токен нашего стенда действует 15 минут.',
     'HS256 использует общий секрет для создания и проверки подписи. Приложение фиксирует разрешённый algorithms=["HS256"] и не доверяет произвольному алгоритму из header. Верификация требует наличия sub и exp, а также ожидаемых iss и aud. Нельзя брать ID из decode без проверки подписи. Роль администратора читаем из актуальной базы; токен не хранит пароль и не заменяет проверку прав.'],
    'Можно ли хранить секретный пароль в payload, если токен подписан?', 'Нет. Подпись защищает целостность, но не скрывает содержимое payload.', ['jwt','jose','ormexamples']);
  add(93,'Bearer-токен идёт в заголовке','После логина клиент прикладывает токен к защищённому запросу.',split(
    c('Следующий HTTP-запрос · шаблон','GET /auth/me HTTP/1.1\nHost: localhost:8007\nAuthorization: Bearer <access_token>'),
    stack(panel('Клиент','Подставляет access_token из ответа логина.','purple'),panel('Сервер','Извлекает токен, проверяет его и получает пользователя.','mint'))),
    'Bearer означает доступ по владению токеном. Его нужно защищать так же внимательно, как данные входа.',
    ['Authorization — имя HTTP-заголовка, Bearer — схема передачи, после пробела идёт полный токен. В примере <access_token> — место для значения, не буквальный текст, который нужно послать серверу. Токен не передаём в query-параметре URL: URL легко оказывается в журналах и истории.',
     'В стенде FastAPI использует HTTPBearer. Через /docs сначала выполняем POST /auth/login с JSON, затем копируем только значение access_token в окно Authorize. Swagger добавляет схему Bearer сам. Порт 8007 выбран для отдельного примера, чтобы не конфликтовать с прежним уроком на 8000.',
     'Перехваченный действительный Bearer-токен может использовать другой человек до завершения его срока или блокировки доступа. Подпись не привязывает токен автоматически к браузеру владельца. Для сетевого развёртывания используют HTTPS и согласованное хранение на клиенте. В учебных файлах сохраняются статусы и публичные ответы, а действительные токены остаются только в памяти проверки.'],
    'Нужно ли передавать свой user_id рядом с Bearer-токеном, чтобы сервер узнал владельца?', 'Нет. Сервер проверяет токен, извлекает sub и получает соответствующего пользователя.', ['bearer','auth','ormexamples']);
  add(94,'get_current_user собирает проверку','Одна зависимость устанавливает пользователя для защищённых маршрутов.',`
    ${flow([['Заголовок','Получить Bearer','yellow'],['JWT','Подпись · exp · iss · aud','purple'],['sub','Проверить ID','yellow'],['users','Найти пользователя','mint']])}
    ${split(c('Псевдокод зависимости','claims = проверить_токен(token)\nuser_id = проверить_ID(claims["sub"])\nuser = найти_пользователя(user_id)\nесли user отсутствует: отказ 401\nвернуть user'),panel('Результат зависимости','Объект User из БД.<br>Следующий шаг проверяет права.','mint'))}`,
    'Валидной подписи недостаточно: пользователь должен существовать, а поля токена — пройти проверку.',
    ['Зависимость сначала извлекает заголовок. Затем python-jose проверяет подпись выбранным ключом, разрешённый алгоритм, срок exp, издателя и получателя. Отсутствие обязательного claim тоже отклоняется. Без этих проверок текст payload не является доверенным источником user_id.',
     'Далее валидируем sub как строковый положительный ID в диапазоне integer и ищем users.id в БД. В примере даже корректно подписанный токен с sub="999" возвращает 401, потому что такого пользователя нет. Ошибки токена превращаем в одинаковый контролируемый отказ, а не отдаём клиенту внутренние подробности криптографии.',
     'Если подпись верна и пользователь найден, get_current_user возвращает ORM-объект. Это аутентификация, а не универсальная авторизация. Роль и владение проверяются после неё. Нельзя ловить вообще все исключения и превращать, например, недоступность PostgreSQL в «неверный пароль»: инфраструктурный сбой имеет другую причину. В примере обрабатываются ожидаемые ошибки JWT и формата ID.'],
    'Токен подписан правильно, но пользователь удалён. Можно продолжить?', 'Нет. get_current_user должен отклонить токен, если соответствующей записи больше нет.', ['jose','auth','ormverified']);
  add(95,'Администратор — отдельная проверка','Сначала получаем пользователя, затем читаем его роль из базы.',split(
    c('api.py · сокращённый фрагмент','def require_admin(\n    user = Depends(get_current_user),\n):\n    if not user.is_admin:\n        raise HTTPException(403)\n    return user'),
    stack(table(['GET /admin/check','Ответ'],[['Аня · is_admin=false','403'],['Администратор · is_admin=true','200']]),panel('Регистрация не выдаёт роль','Публичный запрос с <code>is_admin=true</code> отклоняется.','yellow'))),
    'is_admin берём из текущей записи users. Полям запроса и неподтверждённым claims доверять нельзя.',
    ['require_admin зависит от get_current_user, поэтому неизвестный или неавторизованный клиент сначала получит 401. Если пользователь найден, но is_admin=False, ответ 403. Только после успешной проверки маршруту разрешено выполнять админское действие. В коротком стенде GET /admin/check проверяет доступ без изменения каталога; это вспомогательный маршрут урока.',
     'Первый администратор создаётся локальным seed или отдельной управляемой командой. Регистрация жёстко создаёт обычного пользователя и не принимает роль. В полноценном задании такой зависимостью защитим создание, редактирование и удаление товаров, а также смену статуса заказа.',
     'Мы намеренно читаем is_admin из базы при запросе. В проверке токен с дополнительным is_admin=true не повысил права Ани. После снятия роли у администратора уже выданный токен перестал давать админский доступ, потому что сервер прочитал актуальное значение. Это не означает автоматическое аннулирование всех токенов при смене пароля — политика отзыва требует отдельного механизма.'],
    'Старый токен был выдан администратору. Роль сняли в БД. Что вернёт проверка?', 'В нашем варианте 403: текущая роль читается из базы при каждом защищённом запросе.', ['auth','ormverified']);
  add(96,'Чужой заказ не становится своим','В запросе должны совпасть и ID заказа, и ID его владельца.',split(
    c('Выборка в GET /orders/{order_id}','stmt = select(Order).where(\n    Order.id == order_id,\n    Order.user_id == user.id,\n)\norder = session.scalar(stmt)\nif order is None:\n    raise HTTPException(404)'),
    stack(panel('Аня · user.id = 7','order 501 AND user 7<br>→ <b>200 · заказ найден</b>','mint'),panel('Борис · user.id = 8','order 501 AND user 8<br>→ <b>404 · строки нет в выборке</b>','yellow'))),
    'Предсказуемый ID не даёт доступ. Секретность номера заказа не заменяет проверку владельца.',
    ['Оба пользователя могут знать адрес /orders/501. Аутентификация Бориса проходит: его токен действителен. Затем авторизация ограничивает SELECT двумя условиями одновременно. У заказа 501 user_id=7, поэтому для Бориса с user.id=8 результат None и ответ 404.',
     'Такой фильтр нужен не только для чтения, но и для изменения личных ресурсов. Нельзя сначала найти запись по ID и сразу изменить её, забыв владельца. В некоторых системах применяют отдельную проверку найденной сущности, но она должна быть обязательной на всех путях; в этом примере область видимости выражена прямо в запросе.',
     '404 для чужого и отсутствующего заказа — выбранное поведение, проверенное на обоих случаях. Маршрут здесь предназначен для собственных заказов; роль администратора не даёт скрытого обхода этого фильтра. Если понадобится административный просмотр всех заказов, это будет отдельный явно защищённый контракт. Прятать номера или менять int на UUID вместо проверки прав недостаточно.'],
    'Почему недостаточно одного Order.id == order_id?', 'Потому что любой вошедший пользователь мог бы запросить чужой ID. Второе условие ограничивает запись текущим владельцем.', ['query','auth','ormverified']);
  add(97,'Проверяем не только успешный вход','Меняем одно условие и смотрим, где запрос остановился.',`
    ${control('Сценарий:','auth-case',[['none','Нет токена'],['expired','Токен истёк'],['signature','Неверная подпись'],['missing_user','Пользователь отсутствует'],['valid','Действительный токен Ани'],['not_admin','Аня вызывает админскую проверку'],['admin','Администратор вызывает проверку']])}
    <div id="auth-case-result" aria-live="polite"></div>
    <div class="oa-print-only">${table(['Сценарий','Проверенный ответ'],[['Нет / истёк / неверная подпись','401'],['Нет пользователя / нет exp / другой алгоритм','401'],['Действительный токен → /auth/me','200'],['Обычный пользователь → /admin/check','403'],['Администратор → /admin/check','200']])}</div>`,
    '401 — не удалось установить пользователя. 403 — пользователь известен, но права не подходят.',
    ['Каждый вариант выполнен через FastAPI TestClient с настоящими зависимостями, библиотекой JWT и PostgreSQL. Проверка не подменяет get_current_user фиктивным пользователем. Токен с истёкшим exp создан специально, поэтому тест не ждёт пятнадцать минут и не зависит от случайной паузы.',
     'Для плохой подписи использован другой случайный ключ. Отдельно проверены обязательный exp, запрещённый алгоритм HS512, отсутствие пользователя, обычная и административная роли. Сами действительные токены не записаны в verification.json; сохранены только безопасные публичные ответы и нужные результаты проверок.',
     'Статус сам по себе не доказывает всё поведение. Для чужого заказа дополнительно сравниваем ответ с отсутствующей записью, для регистрации убеждаемся, что наружу не вышли пароль и хэш, для снятой роли повторяем запрос старым токеном. В HTML переключатель воспроизводит зафиксированные результаты. Эти тесты проверяют механизм доступа, а не объявляют короткий стенд полноценной системой управления сессиями.'],
    'Почему истёкший токен даёт 401, а действительный без роли — 403?', 'В первом случае аутентификация не состоялась. Во втором пользователь установлен, но ему запрещено конкретное действие.', ['http','ormverified']);
  add(98,'Практика: найдите место отказа','Токен → пользователь → права → операция. Где закончится каждый запрос?',`
    <div class="db-exercise"><div class="quiz-questions">${table(['Кто и с чем','Запрос'],[['Аня · действительный токен','GET /orders/501'],['Борис · действительный токен','GET /orders/501'],['Аня · истёкший токен','GET /orders/501'],['Аня · обычная роль','GET /admin/check']])}</div>
    <div id="auth-answer" class="quiz-answer" hidden>${table(['Результат','Объяснение'],[['200 · Аня','Токен верен, владелец заказа совпал'],['404 · Борис','Пользователь найден, заказ ему не принадлежит'],['401 · истёкший токен','Остановились в get_current_user'],['403 · обычная роль','Остановились в require_admin']])}</div>
    <button class="reveal-answer" aria-expanded="false" aria-controls="auth-answer">Показать разбор →</button></div>`,
    'Доступ проверяем до выполнения действия. Следующая глава соединит эти правила с оформлением заказа.',
    ['Попросите ученика сначала назвать статус, а затем точное место отказа. Для Ани с действительным токеном get_current_user возвращает пользователя 7, а запрос находит заказ 501 с тем же user_id. Ответ 200. Для Бориса аутентификация успешна, но условие владельца не находит доступного заказа — 404.',
     'Истёкший токен прекращает путь раньше: проверка JWT не проходит, пользователь не установлен, до чтения заказа дело не доходит. При админской проверке Аня установлена успешно, но require_admin видит is_admin=False и отвечает 403. Важно не объяснять все четыре случая одной фразой «токен не подошёл».',
     'В конце ученик должен различать базу, Session, миграцию, хэш, токен и права владельца. Следующий блок — глава 9 — использует эти понятия, чтобы согласованно создать заказ и списать остатки. Здесь останавливаемся на понятном пути защищённого запроса; транзакцию оформления и борьбу за последнюю пару не подменяем краткой проверкой токена.'],
    'Что ещё нужно после успешной проверки токена перед оформлением заказа?', 'Проверить владельца корзины, данные и остатки, затем согласованно выполнить изменения в транзакции. Это следующий блок.', ['ormverified','plan']);

  window.SNEAKER.initChapter78=()=>{
    const $=s=>document.querySelector(s);
    function product(){
      const id=Number($('#orm-product').value), found=id===10;
      const snippet=`stmt = select(Product).where(\n    Product.id == ${id}\n)\nproduct = session.scalar(stmt)`;
      $('#orm-product-result').innerHTML=split(c('SQLAlchemy 2.0 · фрагмент',snippet),result('Результат PostgreSQL',found?'Product\nid = 10\nname = North Runner\nprice = Decimal("7990.00")':'None\n\nОбработчик может вернуть 404'));
    }
    function write(){
      const index=Number($('#orm-write').value), state=verified.orm.write_states[index];
      const snippets=[`product = Product(\n    name="ORM Demo", brand_id=1,\n    price=Decimal("100.00"),\n)`,`session.add(product)`,`session.flush()\n# INSERT уже выполнен\n# Транзакция ещё не зафиксирована`,`session.commit()\n# Транзакция зафиксирована`];
      $('#orm-write-result').innerHTML=split(c(`Шаг ${index+1} · ${state.step}`,snippets[index]),stack(result('Состояние после шага',`product.id = ${state.id??'None'}\nДругое соединение видит строку: ${state.visible_elsewhere?'да':'нет'}`),panel(index===2?'ID появился, commit ещё нет':index===3?'Сохранение завершено':'Пока работаем в памяти',index===2?'После rollback эта вставка исчезнет.':index===3?'Новая транзакция может прочитать строку.':'В этом опыте INSERT ещё не отправлен.',index===3?'mint':'yellow')));
    }
    function auth(){
      const name=$('#auth-case').value, value=verified.auth[name];
      const why={none:'Нет Bearer-токена',expired:'exp уже в прошлом',signature:'Подпись не прошла проверку',missing_user:'В users нет такой записи',valid:'Проверки пройдены, пользователь найден',not_admin:'Пользователь найден, is_admin=false',admin:'Пользователь найден, is_admin=true'}[name];
      $('#auth-case-result').innerHTML=split(stack(c('Запрос',`GET ${value.path}`),panel('Причина результата',why,value.status===200?'mint':'yellow')),`<div class="oa-response"><span class="status ${value.status===200?'':'error'}">${value.status}</span><pre>${esc(JSON.stringify(value.body,null,2))}</pre><p>Ответ сохранён после реального вызова API.</p></div>`);
    }
    $('#orm-product').addEventListener('change',product);product();
    $('#orm-write').addEventListener('change',write);write();
    $('#auth-case').addEventListener('change',auth);auth();
  };
})();
